import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { READ_ONLY_CONFIGURATION_ATTRIBUTE } from "../src/api/api-reference.ts";
import {
  buildOpenApiDocument,
  renderOpenApiDocument,
} from "../src/api/openapi.ts";

export const OPENAPI_OUTPUT_PATH = join(
  import.meta.dir,
  "../../../docs/openapi.json",
);
export const API_REFERENCE_OUTPUT_PATH = join(
  import.meta.dir,
  "../../../docs/api/index.html",
);
export const SCALAR_ASSET_OUTPUT_PATH = join(
  import.meta.dir,
  "../../../docs/api/scalar.js",
);
const SCALAR_ENTRY_PATH = fileURLToPath(
  import.meta.resolve("@scalar/api-reference"),
);
export const SCALAR_ASSET_SOURCE_PATH = join(
  dirname(SCALAR_ENTRY_PATH),
  "browser/standalone.js",
);

export function renderApiReferenceDocument(): string {
  const specification = JSON.stringify(
    buildOpenApiDocument(),
    null,
    2,
  ).replaceAll("<", "\\u003c");
  return `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Werft API Reference</title>
  </head>
  <body>
    <!-- Generated by apps/control-host/scripts/generate-openapi.ts. Do not edit by hand. -->
    <script id="api-reference" type="application/json" ${READ_ONLY_CONFIGURATION_ATTRIBUTE}>
${specification}
    </script>
    <script src="./scalar.js"></script>
  </body>
</html>
`;
}

export function renderScalarAsset(): string {
  return `${readFileSync(SCALAR_ASSET_SOURCE_PATH, "utf8").replace(
    /\n\/\/# sourceMappingURL=.*\n?$/,
    "",
  )}\n`;
}

// The three committed outputs, each paired with what the current source renders.
export function generatedOutputs(): { path: string; content: string }[] {
  return [
    { path: OPENAPI_OUTPUT_PATH, content: renderOpenApiDocument() },
    { path: API_REFERENCE_OUTPUT_PATH, content: renderApiReferenceDocument() },
    { path: SCALAR_ASSET_OUTPUT_PATH, content: renderScalarAsset() },
  ];
}

// After a merge or rebase that conflicted in docs/openapi.json or docs/api/,
// resolve only the source (openapi.ts and the routes), then run this: the
// outputs are rewritten from source, so conflict markers in them do not matter.
// `--check` writes nothing and exits 1 naming each output that differs.
if (import.meta.main) {
  const outputs = generatedOutputs();
  if (process.argv.includes("--check")) {
    const stale = outputs.filter((output) => {
      try {
        return readFileSync(output.path, "utf8") !== output.content;
      } catch {
        return true;
      }
    });
    for (const output of stale) {
      console.error(`stale: ${output.path}`);
    }
    if (stale.length > 0) {
      console.error("run `bun run --cwd apps/control-host openapi:generate`");
      process.exit(1);
    }
    console.log("openapi outputs match the source");
  } else {
    mkdirSync(dirname(API_REFERENCE_OUTPUT_PATH), { recursive: true });
    for (const output of outputs) {
      writeFileSync(output.path, output.content);
      console.log(`wrote ${output.path}`);
    }
  }
}
